const out = $input.first().json || {};

if (out.broker !== 'supabase' || out.rpc_name !== 'gtm_contact_crm_sync_plan_v1') {
  throw new Error('GTM 07 FINAL received unexpected Supabase broker response');
}
if (out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error(`GTM 07 FINAL expected SB-BROKER-V3.0.0, got ${out.broker_version}`);
}

const plan = Array.isArray(out.response) ? out.response : [];

if (plan.length === 0) {
  throw new Error('GTM 07 FINAL failed closed: CRM sync plan is empty');
}

const creates = plan.filter(x => x.sync_action === 'create');
const updates = plan.filter(x => x.sync_action === 'update');
const noops = plan.filter(x => x.sync_action === 'noop');

const unsupported = plan.filter(x => !['create','update','noop'].includes(x.sync_action));
if (unsupported.length) {
  throw new Error('GTM 07 FINAL encountered unsupported sync_action');
}

/*
 * This final workflow deliberately does not auto-write contacts yet.
 * CREATE / UPDATE execution is gated behind the proven ledger claim/finalize
 * contract and will be exercised when new contacts enter the ready set.
 * Current pilot state should be 7 NOOP.
 */
return [{
  json: {
    gtm07_final_plan_completed: true,
    supabase_broker_v3_passed: true,
    supabase_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',
    total_contacts: plan.length,
    create_actions: creates.length,
    update_actions: updates.length,
    noop_actions: noops.length,
    write_required: creates.length + updates.length > 0,
    current_pilot_expected_all_noop:
      plan.length === 7 &&
      creates.length === 0 &&
      updates.length === 0 &&
      noops.length === 7,
    plan,
    next_action:
      creates.length + updates.length === 0
        ? 'No CRM writes required. Handoff is idempotently synchronized.'
        : 'New CRM writes are pending. Use ledger claim/finalize execution path before provider writes.'
  }
}];
